    if (count($worksheet->getParentOrThrow()->getDefinedNames()) > 0) {
        $this->updateDefinedNames($worksheet, $beforeCellAddress, $numberOfColumns, $numberOfRows);
    }

    // Garbage collect
    $worksheet->garbageCollect();
}

